                    WHEN ss.est_monthly_revenue > 0::numeric AND d.in_stock_days_30 >= 7 THEN ss.est_monthly_revenue / d.in_stock_days_30::numeric
                    ELSE NULL::numeric
                END AS baseline_daily_revenue
           FROM pop
             LEFT JOIN ss USING (asin)
